using System;using System.IO;using System.Collections;using UnityEngine;using UnityEditor;using LighthouseKeepers.WatchDemo;using LighthouseKeepers.Core.Progression;
public class LungeLateJoinProbe:MonoBehaviour{
 string folder;public static object Begin(string folder){EditorUtility.audioMasterMute=true;Directory.CreateDirectory(folder);var p=new GameObject("Lunge late-join safety probe").AddComponent<LungeLateJoinProbe>();p.folder=folder;p.StartCoroutine(p.Go());return true;}
 IEnumerator Go(){var t=HorrorTuning.Current;var root=new GameObject("Late join probe root");var feet=new Vector3(0,0,-6.5f);var eye=feet+Vector3.up*1.65f;var c=new ScareSequenceState(t);c.Begin(3,feet+Vector3.forward*.75f);for(int i=0;i<200&&c.Beat!=ScareBeat.Escape;i++)c.Tick(.1f,true,true,0,0);c.Catch(1,feet);var kit=new ScareKit(root.transform);kit.Present(c,eye);yield return new WaitForSeconds(.12f);kit.Present(c,eye);bool ok=!root.transform.Find("Scripted scare kit/Nightmare child").GetComponent<Renderer>().enabled;File.WriteAllText(folder+"/checks.txt",(ok?"PASS ":"FAIL ")+"A late join does not replay an old catch lunge\n");File.WriteAllText(folder+"/result.json","{\"passed\":"+(ok?"true":"false")+"}");kit.Dispose();Destroy(root);Destroy(gameObject);}
}
